WITH scored AS (SELECT id, name, country, city, segment, signup_date, credit_limit, AVG(credit_limit) OVER (PARTITION BY segment) AS segment_avg_credit_limit, AVG(credit_limit) OVER (PARTITION BY country ORDER BY credit_limit, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS credit_limit_avg_6, LAST_VALUE(credit_limit) IGNORE NULLS OVER w_running AS last_known_credit_limit, AVG(credit_limit) OVER (PARTITION BY city, segment) AS city_avg_credit_limit, ROUND(age / SUM(age) OVER (PARTITION BY segment), 4) AS age_share FROM customers WINDOW w_running AS (ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT segment, COUNT(DISTINCT city) AS distinct_cities, COUNT_IF(city = 'Bangkok') AS bangkok_events FROM scored GROUP BY segment ORDER BY bangkok_events NULLS LAST;
